using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace AcxiomCRM.Controllers;
[Authorize] public class OpportunitiesController:Controller { private readonly ApplicationDbContext _db; private readonly IAuditService _audit; public OpportunitiesController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 public async Task<IActionResult> Index(string? q,string? status,int page=1){var query=_db.Opportunities.AsQueryable(); if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier); query=query.Where(x=>x.AssignedTo==uid);} if(!string.IsNullOrWhiteSpace(q)){var s=q.Trim(); query=query.Where(x=>x.OpportunityName.Contains(s));} if(!string.IsNullOrWhiteSpace(status)) query=query.Where(x=>x.Status==status); ViewBag.Query=q;ViewBag.Status=status;ViewBag.Page=page;ViewBag.Pages=(int)Math.Ceiling(await query.CountAsync()/10.0);return View(await query.OrderByDescending(x=>x.Id).Skip((Math.Max(1,page)-1)*10).Take(10).ToListAsync());}
 public async Task<IActionResult> Details(int id){var item=await _db.Opportunities.FindAsync(id);if(item==null)return NotFound();return View(item);}
 
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Opportunity item){if(item.Amount<=0)ModelState.AddModelError(nameof(item.Amount),"Opportunity Amount must be greater than 0.");if(item.Probability<0||item.Probability>100)ModelState.AddModelError(nameof(item.Probability),"Probability must be between 0 and 100.");if(item.Status=="Open"&&item.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(item.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(item);item.CreatedBy=User.FindFirstValue(ClaimTypes.NameIdentifier);if(item is Opportunity assigned && string.IsNullOrEmpty(assigned.AssignedTo)){assigned.AssignedTo=item.CreatedBy;}_db.Opportunities.Add(item);try{await _db.SaveChangesAsync();await _audit.WriteAsync("Create","Opportunity",item.Id.ToString(),newValue:System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Opportunity created successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not save this record. Check for duplicate values and related records.");return View(item);}}
 public async Task<IActionResult> Edit(int id){var item=await _db.Opportunities.FindAsync(id);return item==null?NotFound():View(item);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Opportunity item){if(id!=item.Id)return BadRequest();if(item.Amount<=0)ModelState.AddModelError(nameof(item.Amount),"Opportunity Amount must be greater than 0.");if(item.Probability<0||item.Probability>100)ModelState.AddModelError(nameof(item.Probability),"Probability must be between 0 and 100.");if(item.Status=="Open"&&item.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(item.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(item);var old=await _db.Opportunities.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(old==null)return NotFound();_db.Entry(item).State=EntityState.Modified;_db.Entry(item).Property(x=>x.CreatedDate).IsModified=false;_db.Entry(item).Property(x=>x.CreatedBy).IsModified=false;try{await _db.SaveChangesAsync();await _audit.WriteAsync("Update","Opportunity",id.ToString(),System.Text.Json.JsonSerializer.Serialize(old),System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Opportunity updated successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not update this record. Check duplicate values and relationships.");return View(item);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var item=await _db.Opportunities.FindAsync(id);if(item==null)return NotFound();var old=System.Text.Json.JsonSerializer.Serialize(item);item.Status="Closed";try{await _db.SaveChangesAsync();await _audit.WriteAsync("Delete/Deactivate","Opportunity",id.ToString(),old);TempData["Success"]="Close opportunity completed.";}catch(DbUpdateException){TempData["Error"]="This record is referenced by other records and cannot be deleted. Deactivate it instead.";}return RedirectToAction(nameof(Index));}

}
